package app.trustcam

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Vectors generated by spikes/codec.py — the two implementations MUST stay
 * bit-identical or embedded files stop resolving.
 */
class PayloadCodecTest {
    private val vectors = mapOf(
        1 to Pair(7, "0000000000000000000000010000011100000000000000000000000100000111000000000000000000000001000001110000000000000000000000010000011100000000000000000000000100000111000000000000000000000001000001110000000000000000000000010000011100000000000000000000000100000111"),
        4242 to Pair(160, "0000000000010000100100101010000000000000000100001001001010100000000000000001000010010010101000000000000000010000100100101010000000000000000100001001001010100000000000000001000010010010101000000000000000010000100100101010000000000000000100001001001010100000"),
        82043 to Pair(86, "0000000101000000011110110101011000000001010000000111101101010110000000010100000001111011010101100000000101000000011110110101011000000001010000000111101101010110000000010100000001111011010101100000000101000000011110110101011000000001010000000111101101010110"),
        16777215 to Pair(15, "1111111111111111111111110000111111111111111111111111111100001111111111111111111111111111000011111111111111111111111111110000111111111111111111111111111100001111111111111111111111111111000011111111111111111111111111110000111111111111111111111111111100001111")
    )

    @Test
    fun matchesReferenceCodec() {
        for ((markId, expected) in vectors) {
            val (crc, bits) = expected
            assertEquals("crc8($markId)", crc, PayloadCodec.crc8(markId))
            if (markId < PayloadCodec.MAX_ID) {
                val msg = PayloadCodec.encode(markId)
                assertEquals("bits($markId)", bits,
                    msg.joinToString("") { it.toInt().toString() })
            }
        }
    }
}
